/**
 * Queries whose ENFORCE-mode scope-safe rewrites used to change results. Each query is evaluated with scope safety OFF
 * and ENFORCE, and both must return the SPARQL answer.
 */
class MemoryScopeSafetyEnforceRegressionTest {

	private static final String MODE_PROPERTY = "org.eclipse.rdf4j.query.scopeSafety.mode";
	private static final String EX = "urn:ex:";

	private SailRepository repository;

	@BeforeEach
	void setUp() {
		repository = new SailRepository(new MemoryStore());
		repository.init();
	}

	@AfterEach
	void tearDown() {
		repository.shutDown();
	}

	@Test
	void bindInsideANestedGroupDoesNotSeeOuterBindings() {
		try (RepositoryConnection connection = repository.getConnection()) {
			connection.add(iri("s"), iri("name"), Values.literal("N"));
			connection.add(iri("s"), iri("q"), iri("c"));
			connection.add(iri("c"), iri("r"), iri("d"));
		}
		String query = "PREFIX : <urn:ex:> SELECT * WHERE { ?s :name ?n . ?s :q ?c . "
				+ "{ ?c :r ?d BIND(CONCAT(?n, \"!\") AS ?w) } }";

		List<Map<String, Value>> expected = List.of(row("s", iri("s"), "n", Values.literal("N"), "c", iri("c"),
				"d", iri("d")));
		assertThat(evaluate(query, "off", Map.of())).containsExactlyInAnyOrderElementsOf(expected);
		assertThat(evaluate(query, "enforce", Map.of())).containsExactlyInAnyOrderElementsOf(expected);
	}

	@Test
	void flattenedSubqueryDoesNotSeeOuterVariablesItDoesNotProject() {
		try (RepositoryConnection connection = repository.getConnection()) {
			connection.add(iri("x"), iri("name"), Values.literal("abc"));
			connection.add(iri("x"), iri("p"), iri("y"));
		}
		String query = "PREFIX : <urn:ex:> SELECT * WHERE { ?x :name ?z . "
				+ "{ SELECT ?x ?y WHERE { ?x :p ?y FILTER(CONTAINS(?z, \"a\")) } } }";

		assertThat(evaluate(query, "off", Map.of())).isEmpty();
		assertThat(evaluate(query, "enforce", Map.of())).isEmpty();
	}

	@Test
	void flattenedSubqueryOptionalDoesNotSeeTheSiblingsBinding() {
		try (RepositoryConnection connection = repository.getConnection()) {
			connection.add(iri("s"), iri("w"), Values.literal("1"));
			connection.add(iri("s"), iri("p"), iri("y"));
			connection.add(iri("y"), iri("q"), Values.literal("2"));
		}
		String query = "PREFIX : <urn:ex:> SELECT * WHERE { ?s :w ?w . "
				+ "{ SELECT ?s ?w WHERE { ?s :p ?y OPTIONAL { ?y :q ?w } } } }";

		assertThat(evaluate(query, "off", Map.of())).isEmpty();
		assertThat(evaluate(query, "enforce", Map.of())).isEmpty();
	}

	@Test
	void flattenedSubqueryBindDoesNotOverwriteTheSiblingsBinding() {
		try (RepositoryConnection connection = repository.getConnection()) {
			connection.add(iri("s"), iri("w"), Values.literal("1"));
			connection.add(iri("s"), iri("p"), iri("y"));
		}
		String query = "PREFIX : <urn:ex:> SELECT * WHERE { ?s :w ?w . "
				+ "{ SELECT ?s ?w WHERE { ?s :p ?y BIND(\"2\" AS ?w) } } }";

		assertThat(evaluate(query, "off", Map.of())).isEmpty();
		assertThat(evaluate(query, "enforce", Map.of())).isEmpty();
	}

	@Test
	void preparedBindingIsNotExposedByARemovedProjection() {
		try (RepositoryConnection connection = repository.getConnection()) {
			connection.add(iri("s"), iri("knows"), iri("o"));
		}
		String query = "SELECT ?s ?o WHERE { ?s ?p ?o }";
		Map<String, Value> bindings = Map.of("p", iri("knows"));

		List<Map<String, Value>> expected = List.of(row("s", iri("s"), "o", iri("o")));
		assertThat(evaluate(query, "off", bindings)).containsExactlyInAnyOrderElementsOf(expected);
		assertThat(evaluate(query, "enforce", bindings)).containsExactlyInAnyOrderElementsOf(expected);
	}

	@Test
	void preparedBindingSurvivesProjectionPushdown() {
		try (RepositoryConnection connection = repository.getConnection()) {
			connection.add(iri("s"), iri("knows"), iri("o"));
			connection.add(iri("o"), iri("q"), iri("z"));
		}
		String query = "PREFIX : <urn:ex:> SELECT ?s ?p WHERE { ?s ?p ?o . ?o :q ?z }";
		Map<String, Value> bindings = Map.of("p", iri("knows"));

		List<Map<String, Value>> expected = List.of(row("s", iri("s"), "p", iri("knows")));
		assertThat(evaluate(query, "off", bindings)).containsExactlyInAnyOrderElementsOf(expected);
		assertThat(evaluate(query, "enforce", bindings)).containsExactlyInAnyOrderElementsOf(expected);
	}

	private List<Map<String, Value>> evaluate(String query, String mode, Map<String, Value> bindings) {
		String previous = System.setProperty(MODE_PROPERTY, mode);
		try (RepositoryConnection connection = repository.getConnection()) {
			TupleQuery tupleQuery = connection.prepareTupleQuery(query);
			bindings.forEach(tupleQuery::setBinding);
			List<Map<String, Value>> rows = new ArrayList<>();
			try (TupleQueryResult result = tupleQuery.evaluate()) {
				for (BindingSet bindingSet : result) {
					Map<String, Value> row = new TreeMap<>();
					for (String name : bindingSet.getBindingNames()) {
						Value value = bindingSet.getValue(name);
						if (value != null) {
							row.put(name, value);
						}
					}
					rows.add(row);
				}
			}
			return rows;
		} finally {
			if (previous == null) {
				System.clearProperty(MODE_PROPERTY);
			} else {
				System.setProperty(MODE_PROPERTY, previous);
			}
		}
	}

	private static Map<String, Value> row(Object... namesAndValues) {
		Map<String, Value> row = new TreeMap<>();
		for (int i = 0; i < namesAndValues.length; i += 2) {
			row.put((String) namesAndValues[i], (Value) namesAndValues[i + 1]);
		}
		return row;
	}

	private static IRI iri(String localName) {
		return Values.iri(EX + localName);
	}
}
